$title Diet Problem

* Sets
set i 'variables' /x1 'Corn', x2 'Milk', x3 'Bread'/;
set j 'constraints' /c1*c2/;

* Parameters
parameter c(i) 'objective coefficients' /
    x1 0.18
    x2 0.23
    x3 0.05/;

table A(j,i) 'constraint matrix'
        x       1x       2x       3
    c1    -107    -500       0
    c2     -72    -121     -65
;

parameter b(j) 'right hand side' /
    c1 -500
    c2 -2000/;

* Variables
positive variables x(i) 'decision variables';
free variable obj 'objective value';

* Variable bounds
x.up('x1') = 10;
x.up('x2') = 10;
x.up('x3') = 10;

* Equations
equations
    objective 'objective function'
    constraint1 'constraint 1'
    constraint2 'constraint 2'
;

objective.. obj =e= sum(i, c(i)*x(i));

constraint1.. sum(i, A('c1',i)*x(i)) =l= b('c1');
constraint2.. sum(i, A('c2',i)*x(i)) =l= b('c2');

* Model definition and solution
model diet_problem /all/;
solve diet_problem using lp minimizing obj;

* Display results
display x.l, obj.l;

%% Diet Problem - MATLAB Gurobi Interface
clear; clc;

%% Problem data
c = [0.18, 0.23, 0.05]';  %% Objective coefficients
A = [[-107, -500, 0], [-72, -121, -65]];  %% Constraint matrix
b = [-500, -2000]';  %% Right-hand side

lb = [0, 0, 0]';  %% Lower bounds
ub = [10, 10, 10]';  %% Upper bounds

%% Set up Gurobi model
model.obj = c;
model.A = sparse(A);
model.rhs = b;
model.sense = '<';
model.vtype = 'C';  %% Continuous variables
model.lb = lb;
model.ub = ub;
model.modelsense = 'min';

%% Solve the problem
params.outputflag = 1;
result = gurobi(model, params);

%% Display results
if strcmp(result.status, 'OPTIMAL')
    fprintf('Optimal solution found:\n');
    fprintf('Corn: %.4f\n', result.x(1));
    fprintf('Milk: %.4f\n', result.x(2));
    fprintf('Bread: %.4f\n', result.x(3));
    fprintf('Objective value: %.4f\n', result.objval);
else
    fprintf('Optimization failed: %s\n', result.status);
end

%% Diet Problem - MATLAB Problem-Based Optimization
clear; clc;

%% Create optimization problem
prob = optimproblem('ObjectiveSense', 'minimize');

%% Create optimization variables
Corn = optimvar('Corn', 'LowerBound', 0, 'UpperBound', 10);
Milk = optimvar('Milk', 'LowerBound', 0, 'UpperBound', 10);
Bread = optimvar('Bread', 'LowerBound', 0, 'UpperBound', 10);

%% Define objective function
prob.Objective = 0.18*Corn + 0.23*Milk + 0.05*Bread;

%% Define constraints
prob.Constraints.con1 = -107*Corn + -500*Milk <= -500;
prob.Constraints.con2 = -72*Corn + -121*Milk + -65*Bread <= -2000;

%% Solve the problem
sol = solve(prob);

%% Display results
if ~isempty(sol)
    fprintf('Optimal solution found:\n');
    fprintf('Corn: %.4f\n', sol.Corn);
    fprintf('Milk: %.4f\n', sol.Milk);
    fprintf('Bread: %.4f\n', sol.Bread);
    fprintf('Objective value: %.4f\n', evaluate(prob.Objective, sol));
else
    fprintf('No solution found\n');
end
